insert into public.test_questions (id, test_id, question_text, options, correct_index, explanation, marks, sort_order)
values
  ($m0$tq-aiml-model-parameters-hyperparameters-1$m0$, $m0$mt-aiml-model-parameters-hyperparameters$m0$, $m0$What is a "model" in Machine Learning?$m0$, jsonb_build_array($m0$A) A raw, unprocessed dataset$m0$, $m0$B) The trained system used to make predictions$m0$, $m0$C) A type of hyperparameter$m0$, $m0$D) A visualization tool$m0$), 1, $m0$A model is the complete result of the training process, containing everything the algorithm learned, and is what's actually used to generate predictions.$m0$, 1, 0),
  ($m0$tq-aiml-model-parameters-hyperparameters-2$m0$, $m0$mt-aiml-model-parameters-hyperparameters$m0$, $m0$How are parameters typically determined?$m0$, jsonb_build_array($m0$A) Chosen manually by the developer before training$m0$, $m0$B) Learned automatically by the algorithm during training$m0$, $m0$C) They are never used in Machine Learning$m0$, $m0$D) Randomly guessed with no relation to data$m0$), 1, $m0$Parameters are the internal values (like weights) that the algorithm adjusts automatically based on the training data.$m0$, 1, 1),
  ($m0$tq-aiml-model-parameters-hyperparameters-3$m0$, $m0$mt-aiml-model-parameters-hyperparameters$m0$, $m0$Which of these is an example of a hyperparameter?$m0$, jsonb_build_array($m0$A) The learned slope in Linear Regression$m0$, $m0$B) The number of neighbors (`k`) in KNN$m0$, $m0$C) A specific prediction made by the model$m0$, $m0$D) The size of the training dataset$m0$), 1, $m0$`k` in KNN is a setting chosen manually before training begins, making it a hyperparameter rather than a learned parameter.$m0$, 1, 2),
  ($m0$tq-aiml-model-parameters-hyperparameters-4$m0$, $m0$mt-aiml-model-parameters-hyperparameters$m0$, $m0$When are hyperparameters set, relative to the training process?$m0$, jsonb_build_array($m0$A) During training, automatically$m0$, $m0$B) Before training begins, manually$m0$, $m0$C) After training is complete$m0$, $m0$D) Hyperparameters don't need to be set at all$m0$), 1, $m0$Hyperparameters are configuration choices made by the developer prior to starting the training process.$m0$, 1, 3),
