select $m0$mt-aiml-feature-scaling$m0$, $m0$Feature Scaling — Quick Test$m0$, 'aptitude', 10, 10,
  $m0$A 10-question multiple-choice check on Feature Scaling.$m0$,
  10, 4, true, 'Easy',
