select $m0$mt-aiml-mlops-basics$m0$, $m0$MLOps Basics — Quick Test$m0$, 'aptitude', 10, 10,
  $m0$A 10-question multiple-choice check on MLOps Basics.$m0$,
  10, 4, true, 'Easy',
  g.id, tp.id, 'published', false,
