-- ===========================================================================
-- 6. VALIDATION — raise (never silently pass) if the import is short.
-- ===========================================================================
do $val$
declare v_g uuid; v_sec int; v_top int; v_con int; v_tst int; v_q int; v_prob int;
begin
  select id into v_g from public.learning_grids where lower(slug) = 'ai-ml-notes';
  if v_g is null then raise exception 'ai/ml seed: grid ai-ml-notes missing after seed'; end if;
  select count(*) into v_sec from public.learning_sections where grid_id = v_g;
  select count(*) into v_top from public.learning_topics
    where grid_id = v_g and source_kind = 'ai_ml_notes';
  select count(*) into v_con from public.learning_contents c
    join public.learning_topics t on t.id = c.topic_id
   where t.grid_id = v_g and (c.metadata ->> 'source') = 'ai_ml_notes_seed';
  select count(*) into v_tst from public.practice_tests
   where learning_grid_id = v_g and id like 'mt-aiml-%';
  select count(*) into v_q from public.test_questions q
    join public.practice_tests p on p.id = q.test_id
   where p.learning_grid_id = v_g and p.id like 'mt-aiml-%';
  select count(*) into v_prob from public.dsa_problems
   where learning_grid_id = v_g and topic_id is null and id like 'cp-aiml-%';
  if v_sec <> 1   then raise exception 'ai/ml seed: expected 1 section, got %', v_sec; end if;
  if v_top <> 77  then raise exception 'ai/ml seed: expected 77 topics, got %', v_top; end if;
  if v_con <> 77  then raise exception 'ai/ml seed: expected 77 content blocks, got %', v_con; end if;
  if v_tst <> 69  then raise exception 'ai/ml seed: expected 69 mock tests, got %', v_tst; end if;
  if v_q   <> 690 then raise exception 'ai/ml seed: expected 690 questions, got %', v_q; end if;
  if v_prob <> 196 then raise exception 'ai/ml seed: expected 196 coding problems, got %', v_prob; end if;
  raise notice 'ai/ml seed OK: grid %, % section, % topics, % contents, % tests, % questions, % problems',
    v_g, v_sec, v_top, v_con, v_tst, v_q, v_prob;
end
$val$;

notify pgrst, 'reload schema';
